PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, document TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (user_id TEXT NOT NULL REFERENCES users(id), tenant_id TEXT NOT NULL REFERENCES tenants(id), role TEXT NOT NULL CHECK(role IN ('owner','operator')), PRIMARY KEY(user_id,tenant_id));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), tenant_id TEXT NOT NULL, expires_at INTEGER NOT NULL, FOREIGN KEY(user_id,tenant_id) REFERENCES memberships(user_id,tenant_id));
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', document TEXT NOT NULL DEFAULT '', birthday TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS vehicles (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), customer_id TEXT NOT NULL, plate TEXT NOT NULL, brand TEXT NOT NULL, model TEXT NOT NULL, year INTEGER NOT NULL, color TEXT NOT NULL DEFAULT '', km INTEGER NOT NULL DEFAULT 0 CHECK(km>=0), chassis TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,id), UNIQUE(tenant_id,plate), FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id));
CREATE TABLE IF NOT EXISTS professionals (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'Mecânico', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS catalog (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), kind TEXT NOT NULL CHECK(kind IN ('product','service')), name TEXT NOT NULL, sku TEXT NOT NULL, category TEXT NOT NULL DEFAULT '', cost INTEGER NOT NULL CHECK(cost>=0), price INTEGER NOT NULL CHECK(price>=0), stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), minimum_stock INTEGER NOT NULL DEFAULT 0 CHECK(minimum_stock>=0), active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,id), UNIQUE(tenant_id,sku));
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), number INTEGER NOT NULL, customer_id TEXT NOT NULL, vehicle_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('quote','open','working','ready','completed','cancelled')), entered_on TEXT NOT NULL, due_on TEXT NOT NULL, completed_on TEXT, km INTEGER NOT NULL CHECK(km>=0), problem TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', discount INTEGER NOT NULL DEFAULT 0 CHECK(discount>=0), total INTEGER NOT NULL DEFAULT 0 CHECK(total>=0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,id), UNIQUE(tenant_id,number), FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id), FOREIGN KEY(tenant_id,vehicle_id) REFERENCES vehicles(tenant_id,id));
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, order_id TEXT NOT NULL, catalog_id TEXT NOT NULL, professional_id TEXT, kind TEXT NOT NULL, name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), price INTEGER NOT NULL CHECK(price>=0), cost INTEGER NOT NULL CHECK(cost>=0), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id), FOREIGN KEY(tenant_id,catalog_id) REFERENCES catalog(tenant_id,id), FOREIGN KEY(tenant_id,professional_id) REFERENCES professionals(tenant_id,id));
CREATE TABLE IF NOT EXISTS stock_movements (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, catalog_id TEXT NOT NULL, order_id TEXT, quantity INTEGER NOT NULL, reason TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenant_id,catalog_id) REFERENCES catalog(tenant_id,id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id));
CREATE TABLE IF NOT EXISTS receivables (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, order_id TEXT NOT NULL, customer_id TEXT NOT NULL, description TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>=0), due_on TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','paid')), method TEXT, paid_at TEXT, UNIQUE(tenant_id,id), UNIQUE(tenant_id,order_id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id), FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id));
CREATE TABLE IF NOT EXISTS cash_entries (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, receivable_id TEXT NOT NULL, amount INTEGER NOT NULL, method TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,receivable_id), FOREIGN KEY(tenant_id,receivable_id) REFERENCES receivables(tenant_id,id));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_customers_tenant ON customers(tenant_id,name);
CREATE INDEX IF NOT EXISTS idx_orders_tenant ON orders(tenant_id,status,due_on);
CREATE INDEX IF NOT EXISTS idx_items_order ON order_items(tenant_id,order_id);
CREATE INDEX IF NOT EXISTS idx_receivables_tenant ON receivables(tenant_id,status,due_on);
CREATE INDEX IF NOT EXISTS idx_vehicles_tenant ON vehicles(tenant_id,customer_id);
CREATE INDEX IF NOT EXISTS idx_stock_tenant ON stock_movements(tenant_id,created_at);
INSERT OR IGNORE INTO migrations(version) VALUES(1);
